import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import './CharacterSheet.css';

// --- HELPER FUNCTIONS (Bileşen Dışında Kalsın ki Kod Şişmesin) ---
const parseDice = (diceString) => {
    if (!diceString) return { dice: [], flatBonus: 0 };
    const cleanStr = diceString.replace(/\s+/g, '').toLowerCase();
    const diceRegex = /(\d+)d(\d+)/g;
    const flatRegex = /([+-]\d+)(?!d)/g;
    let dice = []; let match;
    while ((match = diceRegex.exec(cleanStr)) !== null) {
        dice.push({ count: parseInt(match[1]), sides: parseInt(match[2]) });
    }
    let flatBonus = 0;
    while ((match = flatRegex.exec(cleanStr)) !== null) {
        flatBonus += parseInt(match[1]);
    }
    return { dice, flatBonus };
};

const statConfig = {
    Strength: ['Saving Throw', 'Athletics'],
    Dexterity: ['Saving Throw', 'Acrobatics', 'Sleight of Hand', 'Stealth'],
    Constitution: ['Saving Throw'],
    Intelligence: ['Saving Throw', 'Arcana', 'History', 'Investigation', 'Nature', 'Religion'],
    Wisdom: ['Saving Throw', 'Animal Handling', 'Insight', 'Medicine', 'Perception', 'Survival'],
    Charisma: ['Saving Throw', 'Deception', 'Intimidation', 'Performance', 'Persuasion']
};

const CharacterSheet = () => {
    const navigate = useNavigate();
    const [currentStep, setCurrentStep] = useState(1);
    const [character, setCharacter] = useState({
        name: '', charClass: '', level: 1, species: '', playerName: '', expPoints: 0,
        stats: { Strength: 10, Dexterity: 10, Constitution: 10, Intelligence: 10, Wisdom: 10, Charisma: 10 },
        proficiencies: {}, skillOverrides: {},
        armorClass: 10, currentHp: 10, maxHp: 10, speed: 30,
        initiativeOverride: '', weapons: []
    });

    // --- LOGIC ---
    const calculateModifier = (score) => Math.floor((score - 10) / 2);
    const profBonus = Math.ceil(character.level / 4) + 1;

    const handleStatChange = (stat, delta) => {
        setCharacter(prev => ({
            ...prev,
            stats: { ...prev.stats, [stat]: Math.max(1, Math.min(30, prev.stats[stat] + delta)) }
        }));
    };

    const toggleProficiency = (stat, skill) => {
        const key = `${stat}-${skill}`;
        setCharacter(prev => ({
            ...prev,
            proficiencies: { ...prev.proficiencies, [key]: !prev.proficiencies[key] }
        }));
    };

    const handleWeaponChange = (id, field, value) => {
        setCharacter(prev => ({
            ...prev,
            weapons: prev.weapons.map(w => w.id === id ? { ...w, [field]: value } : w)
        }));
    };

    return (
        <div className="sheet-bg">
            <div className="sheet-container">
                {/* --- HEADER (Her Zaman Sabit) --- */}
                <header className="sheet-header">
                    <div className="char-name-container">
                        <input type="text" placeholder="Character Name" value={character.name} onChange={(e) => setCharacter({...character, name: e.target.value})} />
                    </div>
                    <div className="char-details-grid">
                        <div className="detail-box"><input type="number" value={character.level} onChange={(e) => setCharacter({...character, level: e.target.value})} /><label>Level</label></div>
                        <div className="detail-box"><input type="text" value={character.charClass} onChange={(e) => setCharacter({...character, charClass: e.target.value})} /><label>Class</label></div>
                        <div className="detail-box prof-bonus-display"><div className="bonus-value">+{profBonus}</div><label>Proficiency</label></div>
                    </div>
                </header>

                {/* --- STEP 1: STATS & MECHANICS --- */}
                {currentStep === 1 && (
                    <div className="step-content fade-in">
                        <div className="combat-bar">
                            <div className="combat-stat-box shield-box">
                                <input type="number" value={character.armorClass} onChange={(e) => setCharacter({...character, armorClass: e.target.value})} />
                                <label>AC</label>
                            </div>
                            <div className="combat-stat-box hp-box">
                                <div className="hp-inputs">
                                    <input type="number" value={character.currentHp} onChange={(e) => setCharacter({...character, currentHp: e.target.value})} />
                                    <span>/</span>
                                    <input type="number" value={character.maxHp} onChange={(e) => setCharacter({...character, maxHp: e.target.value})} />
                                </div>
                                <label>HP</label>
                            </div>
                            <div className="combat-stat-box speed-box">
                                <input type="number" value={character.speed} onChange={(e) => setCharacter({...character, speed: e.target.value})} />
                                <label>Speed</label>
                            </div>
                        </div>

                        <div className="stats-grid">
                            {Object.keys(statConfig).map((stat) => {
                                const mod = calculateModifier(character.stats[stat]);
                                return (
                                    <div className="stat-group" key={stat}>
                                        <div className="stat-box">
                                            <label>{stat}</label>
                                            <div className="stat-modifier">{mod >= 0 ? `+${mod}` : mod}</div>
                                            <div className="stat-control-pill">
                                                <button onClick={() => handleStatChange(stat, -1)}>−</button>
                                                <div className="stat-score-display">{character.stats[stat]}</div>
                                                <button onClick={() => handleStatChange(stat, 1)}>+</button>
                                            </div>
                                        </div>
                                        <div className="skills-list">
                                            {statConfig[stat].map(skill => {
                                                const key = `${stat}-${skill}`;
                                                const isProf = character.proficiencies[key];
                                                const skillMod = mod + (isProf ? profBonus : 0);
                                                return (
                                                    <div className={`skill-row ${isProf ? 'proficient' : ''}`} key={skill}>
                                                        <div className={`custom-prof-toggle ${isProf ? 'active' : ''}`} onClick={() => toggleProficiency(stat, skill)}></div>
                                                        <span className="skill-bonus">{skillMod >= 0 ? `+${skillMod}` : skillMod}</span>
                                                        <span className="skill-name">{skill}</span>
                                                    </div>
                                                );
                                            })}
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                )}

                {/* --- STEP 2: WEAPONS --- */}
                {currentStep === 2 && (
                    <div className="step-content fade-in">
                        <div className="weapons-section">
                            <div className="section-header">
                                <h2>Attacks</h2>
                                <button className="add-weapon-btn" onClick={() => setCharacter(p => ({...p, weapons: [...p.weapons, {id: Date.now(), name: '', stat: 'Strength', damageDice: ''}]}))}>+ Add</button>
                            </div>
                            <div className="weapons-list">
                                {character.weapons.map(weapon => {
                                    const statMod = calculateModifier(character.stats[weapon.stat]);
                                    const { dice, flatBonus } = parseDice(weapon.damageDice);
                                    const totalDmgBonus = statMod + flatBonus;
                                    const diceDisplay = dice.map(d => `${d.count}d${d.sides}`).join(' + ');

                                    return (
                                        <div className="weapon-card" key={weapon.id}>
                                            <input className="weapon-name" value={weapon.name} onChange={(e) => handleWeaponChange(weapon.id, 'name', e.target.value)} placeholder="Weapon Name" />
                                            <div className="weapon-details-row">
                                                <select value={weapon.stat} onChange={(e) => handleWeaponChange(weapon.id, 'stat', e.target.value)}>
                                                    <option value="Strength">STR</option><option value="Dexterity">DEX</option>
                                                </select>
                                                <input placeholder="Dice (1d8)" value={weapon.damageDice} onChange={(e) => handleWeaponChange(weapon.id, 'damageDice', e.target.value)} />
                                            </div>
                                            <div className="weapon-calc-bar">
                                                <span>ATK: <b className="atk-val">+{statMod + (weapon.isProficient ? profBonus : 0)}</b></span>
                                                <span>DMG: <b className="dmg-val">{diceDisplay || '--'} {totalDmgBonus >= 0 ? `+${totalDmgBonus}` : totalDmgBonus}</b></span>
                                            </div>
                                        </div>
                                    );
                                })}
                            </div>
                        </div>
                    </div>
                )}

                {/* --- FOOTER ACTIONS --- */}
                <div className="sheet-actions">
                    <button className="save-btn" onClick={() => setCurrentStep(currentStep === 1 ? 2 : 1)}>
                        {currentStep === 1 ? "Next Step ➔" : "← Back"}
                    </button>
                </div>
            </div>
        </div>
    );
};

export default CharacterSheet;
